#!/usr/bin/env bash
# ─────────────────────────────────────────────────────────────────────────────
# Regression runner for supabase/migrations/20261012000000_intelligence_canonical_availability.sql
#
#   bash tests/security/regression/run-availability-canonical-pg.sh
#
# Spins up a THROWAWAY PostgreSQL cluster, loads schema_availability_canonical.sql (a placeholder, locked-down
# point_in_time_supply_snapshot() plus the two tables it reads), applies the migration TWICE (idempotency), loads the
# state matrix generated by gen-availability-matrix.mjs FROM THE BROWSER RESOLVER (property-availability.js), and runs
# availability_canonical_regression.sql. The cluster is destroyed on exit. Needs: postgres server binaries + node.
# Exit code: 0 = every state agrees with the browser resolver, the ACL is preserved and the migration is idempotent.
# ─────────────────────────────────────────────────────────────────────────────
set -euo pipefail

HERE="$(cd "$(dirname "$0")" && pwd)"
ROOT="$(cd "$HERE/../../.." && pwd)"
MIGRATION="$ROOT/supabase/migrations/20261012000000_intelligence_canonical_availability.sql"
[[ -f "$MIGRATION" ]] || { echo "FATAL: migration not found: $MIGRATION"; exit 1; }
command -v node >/dev/null || { echo "FATAL: node is required to generate the browser-resolver matrix"; exit 1; }

PGBIN="${PGBIN:-}"
if [[ -z "$PGBIN" ]]; then
  for d in /usr/lib/postgresql/*/bin /usr/local/pgsql/bin /opt/homebrew/opt/postgresql@*/bin; do
    [[ -x "$d/initdb" ]] && PGBIN="$d"
  done
fi
if [[ -z "$PGBIN" ]]; then
  echo "SKIP: could not find initdb. Install PostgreSQL server binaries, or set PGBIN."
  exit 0
fi

RUN_AS=""
if [[ "$(id -u)" -eq 0 ]]; then
  id pgtest >/dev/null 2>&1 || useradd -m pgtest
  RUN_AS="pgtest"
  WORK="$(su pgtest -c 'mktemp -d')"
else
  WORK="$(mktemp -d)"
fi

PGDATA="$WORK/data"
PGSOCK="$WORK/sock"
as_pg() { if [[ -n "$RUN_AS" ]]; then su "$RUN_AS" -c "$1"; else bash -c "$1"; fi; }
cleanup() {
  as_pg "$PGBIN/pg_ctl -D '$PGDATA' -m immediate stop" >/dev/null 2>&1 || true
  rm -rf "$WORK" 2>/dev/null || true
}
trap cleanup EXIT

mkdir -p "$PGSOCK"
[[ -n "$RUN_AS" ]] && chown -R "$RUN_AS" "$WORK"

MATRIX="$WORK/matrix.sql"
node "$HERE/gen-availability-matrix.mjs" > "$MATRIX"
chmod a+r "$MATRIX"

echo "Initialising throwaway PostgreSQL cluster…"
as_pg "$PGBIN/initdb -D '$PGDATA' -A trust -U postgres" >/dev/null
as_pg "$PGBIN/pg_ctl -D '$PGDATA' -o \"-k '$PGSOCK' -h ''\" -l '$PGDATA/server.log' -w start" >/dev/null

PSQL=(psql -h "$PGSOCK" -U postgres -d postgres -v ON_ERROR_STOP=1 -X)

echo "Loading fixture (properties / unit_types + locked-down placeholder function)…"
"${PSQL[@]}" -q -f "$HERE/schema_availability_canonical.sql"

echo "Applying supabase/migrations/$(basename "$MIGRATION") (1st time)…"
"${PSQL[@]}" -q -f "$MIGRATION"
echo "Applying it again (idempotency check — must not error)…"
"${PSQL[@]}" -q -f "$MIGRATION"

echo "Loading the browser-resolver state matrix…"
"${PSQL[@]}" -q -f "$MATRIX"

echo "Running scripts/market-status-report.sql (read-only) and checking it against the browser resolver…"
node "$HERE/gen-availability-matrix.mjs" --expected > "$WORK/expected_report.txt"
chmod a+r "$WORK/expected_report.txt"
REPORT_OUT="$WORK/report_out.txt"
psql -h "$PGSOCK" -U postgres -d postgres -v ON_ERROR_STOP=1 -X -A -t -F'|' -f "$ROOT/scripts/market-status-report.sql" > "$REPORT_OUT"
# section 3: all_listings | available_only (canonical) | available_only (old, market_status only) | total rows
SITE_ROW="$(grep -E '^[0-9]+\|[0-9]+\|[0-9]+\|[0-9]+$' "$REPORT_OUT" | head -1)"
EXP_SITE="$(grep '^SITE|' "$WORK/expected_report.txt")"
GOT_ALL="${SITE_ROW%%|*}"; REST="${SITE_ROW#*|}"; GOT_AV="${REST%%|*}"
[[ "SITE|$GOT_ALL|$GOT_AV" == "$EXP_SITE" ]] || { echo "FAIL — report section 3 (site view) is $SITE_ROW but the browser resolver expects $EXP_SITE"; exit 1; }
# section 6: stored|shown|contactable|count
grep -E '^(available|reserved|rented|fully_occupied|sold|off_market|coming_soon)\|(available|reserved|rented|fully_occupied|sold|off_market|coming_soon)\|[tf]\|[0-9]+$' "$REPORT_OUT" | sed 's/^/SHOWN|/' | sort > "$WORK/got_shown.txt"
grep '^SHOWN|' "$WORK/expected_report.txt" | sort > "$WORK/exp_shown.txt"
if ! diff -u "$WORK/exp_shown.txt" "$WORK/got_shown.txt"; then echo "FAIL — report section 6 (stored -> shown) differs from the browser resolver (diff above)"; exit 1; fi
echo "  ok  report sections 3 and 6 agree with the browser resolver ($(wc -l < "$WORK/exp_shown.txt") stored->shown groups)"

echo "Running assertions…"
if "${PSQL[@]}" -f "$HERE/availability_canonical_regression.sql" 2>&1 | sed 's/^psql:.*NOTICE: *//'; then
  echo
  echo "PASS — every market_status x unit-configuration state matches the browser resolver; ACL preserved; migration idempotent."
else
  echo
  echo "FAIL — a regression assertion did not hold, or the migration was not idempotent (see above)."
  exit 1
fi
